import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let {num_points} distinct points be marked on a circle. We define a *special figure* as a pair `(P, S)`, where `P` is a convex polygon whose vertices are a subset of the {num_points} points, and `S` is a distinguished subset of {subset_size} vertices of `P`. Let `N` be the total number of distinct special figures that can be formed. Find the largest integer `k` such that `2^k` divides `N`.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# m = subset_size, n = num_points
# We want m to be large enough to discourage case analysis on nu_2(C(n,m))
# and n to be large enough to make the problem non-trivial.
m = rng.randint(4, 12)
# n must be > m. We add a buffer to make it more interesting.
n = rng.randint(m + 10, 150)

return {
    'num_points': n,
    'subset_size': m
}

    def verifier(assign):
n = assign['num_points']
m = assign['subset_size']

# Validate constraints from the generator
if not (isinstance(n, int) and isinstance(m, int)):
    return False, None # Must be integers
if not (4 <= m <= 12 and m + 10 <= n <= 150):
    return False, None # Check if parameters are within the generator's range

# Helper function for popcount (sum of binary digits)
def s2(x):
    if x < 0:
        # This case should not be reached with the given constraints
        raise ValueError("Input to s2 must be non-negative")
    return bin(x).count('1')

# The total number of special figures, N, is given by the sum over all possible polygon vertex counts k:
# N = sum_{k=m to n} (ways to choose k vertices for P) * (ways to choose m vertices for S from P)
# N = sum_{k=m to n} C(n, k) * C(k, m)
# Using the identity C(n, k) * C(k, m) = C(n, m) * C(n-m, k-m), the sum becomes:
# N = C(n, m) * sum_{k=m to n} C(n-m, k-m)
# Let j = k-m. The sum is sum_{j=0 to n-m} C(n-m, j) = 2^(n-m).
# So, N = C(n, m) * 2^(n-m).

# We need to find the largest k such that 2^k divides N. This is the 2-adic valuation nu_2(N).
# k = nu_2(N) = nu_2(C(n, m) * 2^(n-m)) = nu_2(C(n, m)) + n - m.

# By Kummer's Theorem, nu_p(C(n, k)) is the number of carries when adding k and n-k in base p.
# For p=2, nu_2(C(n, m)) is the number of carries when adding m and n-m in binary.
# This can be calculated as s2(m) + s2(n-m) - s2(n).
nu2_C_n_m = s2(m) + s2(n-m) - s2(n)

answer = (n - m) + nu2_C_n_m

return True, int(answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
